function eye(closed=false){return `<svg class="eye-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6S2 12 2 12Z"/>${closed?'<path d="M3 3 21 21"/>':'<circle cx="12" cy="12" r="3"/>'}</svg>`;}
