function animateQueue(previous){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('[data-queue-player]').forEach(el=>{const before=previous.get(el.dataset.queuePlayer),after=el.getBoundingClientRect();if(before&&Math.abs(before.left-after.left)>2)el.animate([{transform:'translateX('+(before.left-after.left)+'px)',opacity:.7},{transform:'translateX(0)',opacity:1}],{duration:380,easing:'cubic-bezier(.2,.8,.2,1)'});});}
