function noteText(n){return n.kind==='risk_scanner'?(n.exact?'':'Approx. ')+Math.round(n.p*100)+'% mine risk':n.kind==='postulate'?n.points+' base points if safe':['plant_mine','silent_mine'].includes(n.kind)?n.added?'Mine placed.':'Already mined; no mine added.':n.isMine?'Mine':'Safe';}
