  const bravest=[...players].filter(p=>stats(p).bravestGuess!==null).sort((a,b)=>stats(b).bravestGuess-stats(a).bravestGuess)[0],hits=[...players].sort((a,b)=>stats(b).minesHit-stats(a).minesHit)[0],streak=[...players].filter(p=>stats(p).maxStreak>=3).sort((a,b)=>stats(b).maxStreak-stats(a).maxStreak)[0],next=state.nextRound;
