    content='<div class="live-hud"><div class="turn-banner '+(state.turnId===me?'your-turn':'')+'" style="--player-color:'+(turn?.color||color)+'"><div><div class="turn-label '+(animate&&turn?'turn-enter':'')+'">'+(preparing?'Preparation':turn?esc(turn.name)+(turn.id===me?' (you) — your turn':' — playing'):'Waiting for a player')+'</div><div class="turn-sub">'+(preparing?'Choose anytime items. Board changes unlock after the first clear.':state.foggedId===me?'Fog hides your numbers this turn.':player?.spectator?'Spectating until the next game.':player?.lives===0?'Out this round.':state.board.firstMove&&canReveal()?'First click anywhere: a safe opening and a points bonus.':canReveal()?'Reveal a cell or use an item.':'Use anytime items and flags while waiting.')+'</div></div>'+(preparing?'<span class="small muted">GET READY</span>':'<div class="clock" id="clock"><span>'+(state.settings.timer?'TIME LEFT':'NO TIMER')+'</span><strong id="countdown">—</strong></div>')+'</div></div>'+queueMarkup()+'<div class="game-layout">'+sidebar()+boardMarkup()+'</div>'+mobileItemTray();
