function fitBoard(){
  document.querySelectorAll('.board.fit-all').forEach(board=>{
    const frame=board.closest('.board-scroll'),cols=state.board.width,rows=state.board.height,gap=parseFloat(getComputedStyle(board).gap)||0,live=['preparing','playing'].includes(state.phase);
    const width=frame.clientWidth-24,height=live?frame.clientHeight-24:Math.min(430,window.innerHeight-220);
    const size=Math.floor(Math.min(56,(width-gap*(cols-1))/cols,(height-gap*(rows-1))/rows));
    board.style.setProperty('--cell-size',Math.max(1,size)+'px');board.style.setProperty('--fit-font',Math.max(5,Math.min(23,size*.52))+'px');
    board.style.setProperty('--note-font',Math.max(6,Math.min(12,size*.27))+'px');
  });applyBoardView();
}
function applyBoardView(){
  const stage=document.querySelector('.game-layout .board-stage');if(!stage)return;
  const frame=stage.closest('.board-scroll'),limitX=Math.max(0,(stage.offsetWidth*boardView.scale-frame.clientWidth)/2+12),limitY=Math.max(0,(stage.offsetHeight*boardView.scale-frame.clientHeight)/2+12);
  boardView.x=Math.max(-limitX,Math.min(limitX,boardView.x));boardView.y=Math.max(-limitY,Math.min(limitY,boardView.y));
  stage.style.transform='translate('+boardView.x+'px,'+boardView.y+'px) scale('+boardView.scale+')';
  const label=document.querySelector('.zoom-reset');if(label)label.textContent=Math.round(boardView.scale*100)+'%';
}
function zoomBoard(factor,x,y){
  const frame=document.querySelector('.game-layout .board-scroll');if(!frame)return;
  const bounds=frame.getBoundingClientRect(),old=boardView.scale,next=Math.max(.6,Math.min(5,old*factor));
  const anchorX=(x??bounds.left+bounds.width/2)-bounds.left-bounds.width/2,anchorY=(y??bounds.top+bounds.height/2)-bounds.top-bounds.height/2;
  boardView.x=anchorX-(anchorX-boardView.x)*next/old;boardView.y=anchorY-(anchorY-boardView.y)*next/old;boardView.scale=next;applyBoardView();
}
window.addEventListener('resize',fitBoard);
function updateClock(){if(!state)return;document.querySelectorAll('[data-hidden-until]').forEach(el=>{el.textContent='◌ Hidden '+Math.max(0,Math.ceil((Number(el.dataset.hiddenUntil)-Date.now()-clockOffset)/1000))+'s';});document.querySelectorAll('[data-curse-until]').forEach(el=>{el.textContent='⛓ Items locked '+Math.max(0,Math.ceil((Number(el.dataset.curseUntil)-Date.now()-clockOffset)/1000))+'s';});const deadline=state.phase==='preparing'?state.previewUntil:state.deadline,seconds=deadline?Math.max(0,Math.ceil((deadline-Date.now()-clockOffset)/1000)):null;if($('countdown'))$('countdown').textContent=seconds===null?'∞':`${seconds}s`;if($('clock'))$('clock').classList.toggle('urgent',state.phase==='playing'&&seconds!==null&&seconds<=3);if($('prep-countdown'))$('prep-countdown').textContent=`${seconds??0}s`;}
setInterval(updateClock,100);
function inviteURL(){const url=new URL(location.href);url.search='';url.searchParams.set('room',state.code);return url.toString();}
async function share(){try{await navigator.clipboard.writeText(inviteURL());toast('Invite link copied.');}catch{toast(`Room code: ${state.code}. Copy the address-bar link.`);}}
async function leaveRoom(){resetRoom();window.scrollTo(0,0);try{await request('leave-room',{});}catch{socket.disconnect();socket.connect();}}
document.querySelector('.wordmark').onclick=e=>{if(me||session){e.preventDefault();leaveRoom();}};
async function cellAction(index,forceFlag=null){
  if(ghostMode){const kind=ghostMode;ghostMode=null;await action('ghost-action',{kind,index});renderRoom();return;}
  const selected=inventory.find(i=>i.uid===selectedItem),revealedTarget=selected&&['revealed-cell','revealed','number'].includes(selected.target);
  if(state.board.cells[index].revealed&&(!revealedTarget||forceFlag))return;
  if(forceFlag===null&&selectedItem){const card=inventory.find(i=>i.uid===selectedItem);if(card?.target==='item'){toast('Choose a highlighted card in your hand.');return;}if(card?.target==='player'){toast('Choose a player.');return;}if(card?.target==='player-cell'&&!selectedTargetPlayer){toast('Choose a player first.');return;}const uid=selectedItem,playerId=selectedTargetPlayer;selectedItem=null;selectedTargetPlayer=null;await action('use-item',{uid,index,playerId});renderRoom();return;}
  if(forceFlag===null&&state.phase==='targeting'&&state.forceChooser===me){await action('force-target',{index});return;}
  const flag=forceFlag===null?mode==='flag':forceFlag;if(flag?!canFlag():!canReveal()){toast(state?.phase==='preparing'&&!flag?'Wait for preparation to finish.':flag?'Flags are for living players.':'Wait for your turn.');return;}
  const had=(flagVisibility==='private'?privateFlags:ownSharedFlags).has(index),ok=await action(flag?'flag':'reveal',{index,...(flag?{visibility:flagVisibility}:{})});if(ok&&flag)toast(`${flagVisibility==='private'?'Private':'Shared'} flag ${had?'removed':'placed'}.`);
}
$('room-view').onclick=async e=>{
  const ghostTarget=e.target.closest('[data-ghost-target-player]');if(ghostMode==='spook'&&ghostTarget&&!e.target.closest('button')){ghostMode=null;await action('ghost-action',{kind:'spook',playerId:ghostTarget.dataset.ghostTargetPlayer});renderRoom();return;}
  const tile=e.target.closest('[data-cell]');if(tile){if(held||Date.now()-lastHoldAt<600){held=false;return;}if(['playing','preparing','targeting'].includes(state.phase))await cellAction(Number(tile.dataset.cell));return;}
  const card=e.target.closest('[data-draft-pick]');if(card){if(draftSelecting)return;draftSelecting=true;pendingDraftKey=draft?.offers.map(c=>c.uid).join(',')||'';selectedDraftUid=card.dataset.draftPick;const uid=selectedDraftUid;document.querySelectorAll('[data-draft-pick]').forEach(el=>{el.disabled=true;el.classList.add(el===card?'draft-selected':'draft-dismiss');});await new Promise(resolve=>setTimeout(resolve,150));const ok=await action('draft-pick',{uid});if(draftSelecting||!ok){draftSelecting=false;selectedDraftUid=null;pendingDraftKey='';renderRoom();}return;}
  const playerButton=e.target.closest('[data-target-player]');if(playerButton&&selectedItem&&!e.target.closest('[data-kick]')&&!e.target.closest('[data-use-item]')){const item=inventory.find(i=>i.uid===selectedItem);selectedTargetPlayer=playerButton.dataset.targetPlayer;if(['player','cell-or-player'].includes(item?.target)){const uid=selectedItem,playerId=selectedTargetPlayer;selectedItem=null;selectedTargetPlayer=null;await action('use-item',{uid,playerId});}renderRoom();return;}
  const itemButton=e.target.closest('[data-use-item]');if(itemButton&&!itemButton.disabled){const item=inventory.find(i=>i.uid===itemButton.dataset.useItem);if(inventory.find(i=>i.uid===selectedItem)?.id==='echo_shard'&&item.uid!==selectedItem){const uid=selectedItem;selectedItem=null;selectedTargetPlayer=null;await action('use-item',{uid,targetUid:item.uid});renderRoom();}else if(item?.target){ghostMode=null;selectedItem=selectedItem===item.uid?null:item.uid;selectedTargetPlayer=null;renderRoom();}else{itemButton.disabled=true;const ok=await action('use-item',{uid:item.uid});if(!ok&&itemButton.isConnected)itemButton.disabled=false;}return;}
  const swatch=e.target.closest('[data-room-color]');if(swatch){await action('color',{color:swatch.dataset.roomColor,shade});return;}
  const kick=e.target.closest('[data-kick]');if(kick){kickTarget=kick.dataset.kick;const p=state.players.find(p=>p.id===kickTarget);$('kick-description').textContent=`Remove ${p?.name||'this player'} from the room?`;$('kick-dialog').showModal();return;}
  const button=e.target.closest('[data-command]');if(!button||button.disabled)return;const command=button.dataset.command;
  if(command==='ghost-flag'||command==='ghost-spook'){ghostMode=command==='ghost-flag'?'flag':'spook';selectedItem=null;renderRoom();}else if(command==='share')share();else if(command==='help')openHelp();else if(command==='toggle-mode'){mode=mode==='reveal'?'flag':'reveal';selectedItem=null;renderRoom();}else if(command==='toggle-visibility'){flagVisibility=flagVisibility==='shared'?'private':'shared';save('sweep-flag-visibility',flagVisibility);renderRoom();}else if(command==='reset-zoom'){boardView={scale:1,x:0,y:0};applyBoardView();}else if(command==='players'){showPlayers=!showPlayers;renderRoom();}else if(command==='debug'){renderDebug();$('debug-dialog').showModal();}else if(command==='cancel-item'){selectedItem=null;selectedTargetPlayer=null;renderRoom();}else if(command==='leave')leaveRoom();else if(command==='draft-reroll'){if(draftSelecting)return;draftSelecting=true;pendingDraftKey=draft?.offers.map(c=>c.uid).join(',')||'';document.querySelectorAll('[data-draft-pick]').forEach(el=>{el.disabled=true;el.classList.add('draft-dismiss');});await new Promise(resolve=>setTimeout(resolve,150));const ok=await action(command);if(draftSelecting||!ok){draftSelecting=false;pendingDraftKey='';renderRoom();}}else{button.disabled=true;const ok=await action(command);if(!ok&&button.isConnected)button.disabled=false;}
};
$('room-view').onchange=e=>{
 if(e.target.matches('[data-bot-difficulty]')){action('bot-difficulty',{playerId:e.target.dataset.botDifficulty,difficulty:e.target.value});return;}
 if(e.target.id==='room-shade'){action('color',{color:baseColor,shade:Number(e.target.value)});return;}
 const fields={'rounds-setting':'rounds','timer-setting':'timer','preview-setting':'preview','lives-setting':'lives','debug-setting':'debug','difficulty-setting':'difficulty','pool-setting':'itemPool'},field=fields[e.target.id];if(!field)return;
 const value=field==='debug'?e.target.checked:['rounds','timer','preview','lives'].includes(field)?Number(e.target.value):e.target.value;settingsDraft={...(settingsDraft||state.settings),[field]:value};const payload={...settingsDraft};settingsPending++;settingsQueue=settingsQueue.then(()=>action('settings',payload)).finally(()=>settingsPending--);
};
$('close-kick').onclick=$('cancel-kick').onclick=()=>{$('kick-dialog').close();kickTarget=null;};
$('confirm-kick').onclick=async()=>{const id=kickTarget;$('kick-dialog').close();kickTarget=null;if(id)await action('kick',{playerId:id});};
$('room-view').addEventListener('contextmenu',e=>{const tile=e.target.closest('[data-cell]');if(tile){e.preventDefault();clearTimeout(holdTimer);if(held||Date.now()-lastHoldAt<600)return;if(pointerStart){held=true;lastHoldAt=Date.now();pointerStart=null;}cellAction(Number(tile.dataset.cell),mode!=='flag');}});
$('room-view').addEventListener('pointerdown',e=>{const tile=e.target.closest('[data-cell]');if(!tile||e.pointerType==='mouse')return;held=false;pointerStart={x:e.clientX,y:e.clientY};const index=Number(tile.dataset.cell);holdTimer=setTimeout(()=>{held=true;lastHoldAt=Date.now();pointerStart=null;cellAction(index,true);if(navigator.vibrate)navigator.vibrate(20);},500);});
document.addEventListener('pointerup',()=>{clearTimeout(holdTimer);pointerStart=null;});document.addEventListener('pointercancel',()=>{clearTimeout(holdTimer);pointerStart=null;});document.addEventListener('pointermove',e=>{if(pointerStart&&Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>10){clearTimeout(holdTimer);pointerStart=null;}});

function mobileItemTray(){const p=state.players.find(p=>p.id===me);return p&&!p.spectator?`<section class="owner-item-tray" aria-label="Your items"><div class="tray-label">Your items ${state.settings.debug&&state.hostId===me?'<button class="text-button" data-command="debug">Debug +</button>':''}</div>${statusMarkup(p)}${inventoryMarkup(p)||'<span class="small muted">No items yet.</span>'}</section>`:'';}

