  $('debug-item-list').innerHTML=catalog.map(c=>'<button class="debug-item '+c.rarity+'" data-debug-grant="'+c.id+'" '+(!enabled||inventory.some(i=>i.id===c.id)||c.needsLives&&state.settings.lives===0?'disabled':'')+'><strong>'+c.icon+' '+esc(c.name)+'</strong><span>'+c.rarity+' · '+(inventory.some(i=>i.id===c.id)?'Already owned':c.when.replaceAll('-',' '))+'</span><small>'+esc(cardDescription(c))+'</small>'+cardTutorials(c)+'</button>').join('');
