const gestures=new Map();let gestureDistance=0,gestureCenter=null;
$('room-view').addEventListener('wheel',e=>{if(!e.target.closest('.game-layout .board-scroll'))return;e.preventDefault();zoomBoard(Math.exp(-e.deltaY*.002),e.clientX,e.clientY);},{passive:false});
document.addEventListener('keydown',e=>{if(!['playing','preparing'].includes(state?.phase)||e.target.closest('input,select,textarea')||document.querySelector('dialog[open]'))return;if(e.key.toLowerCase()==='f'){e.preventDefault();mode=mode==='reveal'?'flag':'reveal';selectedItem=null;renderRoom();}if(e.key.toLowerCase()==='v'){e.preventDefault();flagVisibility=flagVisibility==='private'?'shared':'private';save('sweep-flag-visibility',flagVisibility);renderRoom();}if(['+','=','-','_'].includes(e.key)){e.preventDefault();zoomBoard(['+','='].includes(e.key)?1.2:1/1.2);}if(e.key==='0'){boardView={scale:1,x:0,y:0};applyBoardView();}});
$('room-view').addEventListener('pointerdown',e=>{
  const frame=e.target.closest('.game-layout .board-scroll');if(!frame)return;
  if(e.pointerType==='mouse'&&e.button!==1&&boardView.scale<=1)return;
  if(e.pointerType==='mouse'&&e.button===1)e.preventDefault();
  gestures.set(e.pointerId,{x:e.clientX,y:e.clientY,drag:e.pointerType==='mouse'});if(e.pointerType==='mouse'&&e.button===1)frame.setPointerCapture(e.pointerId);
  if(gestures.size===2){clearTimeout(holdTimer);pointerStart=null;const [a,b]=[...gestures.values()];gestureDistance=Math.hypot(a.x-b.x,a.y-b.y);gestureCenter={x:(a.x+b.x)/2,y:(a.y+b.y)/2};}
});
$('room-view').addEventListener('pointermove',e=>{
  const old=gestures.get(e.pointerId);if(!old)return;
  const dx=e.clientX-old.x,dy=e.clientY-old.y;gestures.set(e.pointerId,{...old,x:e.clientX,y:e.clientY});
  if(gestures.size>=2){const [a,b]=[...gestures.values()],distance=Math.hypot(a.x-b.x,a.y-b.y),center={x:(a.x+b.x)/2,y:(a.y+b.y)/2};if(gestureDistance>0)zoomBoard(distance/gestureDistance,center.x,center.y);if(gestureCenter){boardView.x+=center.x-gestureCenter.x;boardView.y+=center.y-gestureCenter.y;applyBoardView();}gestureDistance=distance;gestureCenter=center;}
  else if(old.drag||boardView.scale>1){boardView.x+=dx;boardView.y+=dy;applyBoardView();}
  else return;
  if(Math.abs(dx)+Math.abs(dy)>1){clearTimeout(holdTimer);pointerStart=null;held=true;lastHoldAt=Date.now();}
});
const endGesture=e=>{if(gestures.has(e.pointerId)){gestures.delete(e.pointerId);if(held)lastHoldAt=Date.now();}gestureDistance=0;gestureCenter=null;};
document.addEventListener('pointerup',endGesture);document.addEventListener('pointercancel',endGesture);


